(()=>{
'use strict';
const APP='sec-simulator-v1',SESSION='sec-session-v1';
const root=document.querySelector('#app'),toastRoot=document.querySelector('#toast');
const now=()=>new Date().toISOString(),id=(p='id')=>`${p}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,7)}`;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),round=(n,d=2)=>Number(Number(n).toFixed(d));
const esc=(s='')=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=(n,d=2)=>`$${Number(n||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d})}`;
const pct=(n,sign=false)=>`${sign&&Number(n)>0?'+':''}${Number(n||0).toFixed(2)}%`;
const cls=n=>n>0?'up':n<0?'down':'';
const tri=n=>n>0?'▲':n<0?'▼':'—';
const I=(name)=>{const p={
 close:'<path d="M18 6 6 18M6 6l12 12"/>',more:'<circle cx="5" cy="12" r="1" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1" fill="currentColor" stroke="none"/><circle cx="19" cy="12" r="1" fill="currentColor" stroke="none"/>',
 user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',exchange:'<path d="M20 7h-9M15 3l-4 4 4 4M4 17h9M9 13l4 4-4 4"/>',portfolio:'<rect x="3" y="6" width="18" height="13" rx="2"/><path d="M8 6V4h8v2M3 11h18"/>',news:'<path d="M4 5h16v14H4zM8 9h8M8 13h8M8 17h5"/>',overview:'<path d="M4 18V9M10 18V5M16 18v-7M22 18V3"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',right:'<path d="m9 18 6-6-6-6"/>',left:'<path d="m15 18-6-6 6-6"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',chart:'<path d="M3 20h18M5 16l4-5 4 3 6-9"/>',home:'<path d="m3 11 9-8 9 8v10h-6v-6H9v6H3z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 15a1.7 1.7 0 0 0 .3 1.9l-2.4 2.4A1.7 1.7 0 0 0 15 19l-1 .4V22h-4v-2.6L9 19a1.7 1.7 0 0 0-1.9.3l-2.4-2.4A1.7 1.7 0 0 0 5 15l-.4-1H2v-4h2.6L5 9a1.7 1.7 0 0 0-.3-1.9l2.4-2.4A1.7 1.7 0 0 0 9 5l1-.4V2h4v2.6l1 .4a1.7 1.7 0 0 0 1.9-.3l2.4 2.4A1.7 1.7 0 0 0 19 9l.4 1H22v4h-2.6z"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3M14 3h5a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15"/>',play:'<path d="m8 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="1"/>',next:'<path d="m5 4 10 8-10 8ZM19 5v14"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>',download:'<path d="M12 3v12M7 10l5 5 5-5M4 21h16"/>',upload:'<path d="M12 21V9M7 14l5-5 5 5M4 3h16"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.chart}</svg>`};
const stocks=()=>[
 ['ORI','Oriental Retail International','Retail','Asia',143.53,141.45,1.47,'A major consumer retail group operating supermarkets, logistics networks and digital commerce platforms across Asia.'],
 ['BRCK','Brickstone Aviation','Aviation','North America',322.22,323.06,-.26,'An international aviation company with passenger, cargo and aircraft service operations.'],
 ['ASD','Aster Dynamics','Manufacturing','Europe',89.16,88.61,.62,'A diversified manufacturer focused on industrial automation, precision components and factory systems.'],
 ['SUN','Sunrise Motors','Automotive','Asia',72.90,73.03,-.18,'An electric and hybrid vehicle manufacturer with battery and mobility businesses.'],
 ['BTS','Bright Tech Systems','Technology','Asia',35.19,35.10,.26,'A computing products and consumer electronics company serving global markets.'],
 ['BCK','Black Creek Energy','Energy','North America',486.13,484.58,.32,'A large integrated energy producer with conventional and renewable assets.'],
 ['DON','Donwell Foods','Consumer','Europe',27.20,27.16,.15,'A packaged food and ingredients company with distribution across Europe and Asia.'],
 ['DMG','DMG Media Group','Media','Global',318.44,319.92,-.46,'A global digital media, entertainment and advertising business.'],
 ['MAP','Maple Health','Healthcare','North America',38.45,38.42,.09,'A healthcare services and medical technology company focused on accessible diagnostics.'],
 ['GWR','GreenWave Robotics','Technology','Europe',24.99,24.63,1.46,'A robotics company building warehouse, agriculture and light industrial automation systems.'],
 ['NAG','North Atlantic Group','Finance','Europe',65.33,65.50,-.26,'A banking and financial services group serving consumer and commercial clients.'],
 ['WAG','West Arc Goods','Consumer','North America',27.20,27.24,-.15,'A branded household goods business with retail and direct-to-consumer channels.'],
 ['NLL','NovaLink Logistics','Logistics','Global',54.45,54.40,.09,'A global logistics operator providing freight, warehousing and last-mile delivery.'],
 ['PNP','Pioneer Pharma','Healthcare','Europe',143.53,141.45,1.47,'A pharmaceutical company researching treatments in oncology, immunology and rare disease.'],
 ['XRD','Xeridian Cloud','Technology','North America',686.13,683.94,.32,'A cloud infrastructure and enterprise artificial intelligence platform provider.'],
 ['LFE','Life Frontier','Healthcare','Asia',111.12,111,.11,'A health technology company producing connected devices and preventative care services.'],
 ['SFE','Safe Earth Utilities','Energy','Europe',97.07,97.41,-.35,'A regulated utility investing in power grids, storage and renewable generation.']
].map((x,i)=>({ticker:x[0],name:x[1],sector:x[2],region:x[3],price:x[4],previous:x[5],change:x[6],description:x[7],watch:[0,1,3,13].includes(i),history:Array.from({length:12},(_,j)=>round(x[4]*(.9+j*.009+Math.sin(j+i)*.008),2))}));
const news=()=>[
 {id:'n1',title:'Digital ads mirror pandemic trends',body:'The computing products and consumer electronics industry accounts for the bulk of digital advertising spending. Analysts forecast that technology companies will increase digital ad investment this year, representing one of the fastest growth rates across major industries.',category:'market',scope:'Industry',targets:['Technology'],sentiment:'positive',impact:.65,duration:2,round:1,day:3,published:true,fake:false},
 {id:'n2',title:'Global auto sales surge as battery prices fall',body:'Lower battery input costs and stronger demand for electric vehicles are improving the outlook for automotive manufacturers. Companies with established supply chains may benefit more quickly than smaller competitors.',category:'market',scope:'Industry',targets:['Automotive'],sentiment:'positive',impact:.8,duration:2,round:1,day:8,published:true,fake:false},
 {id:'n3',title:'Public health emergency disrupts international travel',body:'A new international health emergency is expected to reduce passenger travel and disrupt some physical retail activity. Healthcare and digital service companies may experience increased demand.',category:'market',scope:'World',targets:['Aviation','Retail','Healthcare','Technology'],sentiment:'mixed',impact:.9,duration:5,round:1,day:11,published:true,fake:false},
 {id:'n4',title:'ORI opens automated distribution center',body:'Oriental Retail International has opened a new automated distribution center. Management expects the facility to reduce delivery times and improve inventory turnover.',category:'company',scope:'Company',targets:['ORI'],sentiment:'positive',impact:.75,duration:2,round:1,day:6,published:true,fake:false},
 {id:'n5',title:'BRCK faces temporary route restrictions',body:'Several high-volume international routes will operate under temporary restrictions. BRCK expects a short-term effect on passenger capacity but says cargo operations remain stable.',category:'company',scope:'Company',targets:['BRCK'],sentiment:'negative',impact:.7,duration:3,round:1,day:10,published:true,fake:false},
 {id:'n6',title:'Pioneer Pharma reports encouraging trial data',body:'Pioneer Pharma has reported encouraging early-stage data for a new treatment. The company cautioned that additional trials are still required before any regulatory submission.',category:'company',scope:'Company',targets:['PNP'],sentiment:'positive',impact:1,duration:2,round:1,day:14,published:true,fake:false},
 {id:'n7',title:'Celebrity photographed near DMG headquarters',body:'A well-known entertainer was photographed near DMG Media Group headquarters. The visit has not been linked to any announced commercial project.',category:'company',scope:'Company',targets:['DMG'],sentiment:'neutral',impact:0,duration:1,round:1,day:17,published:true,fake:true}
];
const fresh=()=>({code:'SEC2026',name:'SEC Simulator',adminPassword:'SEC2026',settings:{rounds:3,days:20,tradeSeconds:40,restSeconds:20,initial:100000,fee:.0015},status:'waiting',phase:'trading',round:1,day:1,remaining:40,lastTick:Date.now(),stocks:stocks(),news:news(),players:[],activity:[{id:id('a'),title:'Game created',detail:'Round 1 is waiting to start',at:now()}],demo:[{id:'d1',name:'Z&Z',roi:34.83},{id:'d2',name:'miracle',roi:25.42},{id:'d3',name:'nsjsj',roi:11.79}]});
const load=()=>{try{const g=JSON.parse(localStorage.getItem(APP));return g&&g.stocks?g:fresh()}catch{return fresh()}};
let game=load(),session=JSON.parse(localStorage.getItem(SESSION)||'null');
let ui={role:'player',page:'exchange',tab:'all',newsTab:'market',search:'',searchOpen:false,detail:null,modal:null,tradeSide:'buy',qty:0,admin:'dashboard',adminSearch:''};
const save=()=>{game.updatedAt=now();localStorage.setItem(APP,JSON.stringify(game))};
const saveSession=()=>session?localStorage.setItem(SESSION,JSON.stringify(session)):localStorage.removeItem(SESSION);
const player=()=>session?.role==='player'?game.players.find(p=>p.id===session.playerId):null;
const stock=t=>game.stocks.find(s=>s.ticker===t);
const holding=(p,t)=>p?.holdings?.[t]||{shares:0,avg:0};
const pvalue=p=>Object.entries(p?.holdings||{}).reduce((a,[t,h])=>a+(stock(t)?.price||0)*h.shares,0);
const assets=p=>Number(p?.cash||0)+pvalue(p),roi=p=>(assets(p)-game.settings.initial)/game.settings.initial*100;
const latest=()=>game.news.filter(n=>n.published&&((n.round<game.round)||(n.round===game.round&&n.day<=game.day))).sort((a,b)=>(b.round*100+b.day)-(a.round*100+a.day))[0];
const leaders=()=>[...game.players.map(p=>({id:p.id,name:p.name,roi:roi(p),player:p})),...game.demo].sort((a,b)=>b.roi-a.roi);
const addActivity=(title,detail)=>{game.activity.unshift({id:id('a'),title,detail,at:now()});game.activity=game.activity.slice(0,20)};
const toast=(text,type='success')=>{const d=document.createElement('div');d.className=`toast ${type}`;d.textContent=text;toastRoot.append(d);setTimeout(()=>d.remove(),2800)};
const status=()=>game.status==='ended'?'GAME ENDED':game.status==='waiting'?'WAITING FOR START':game.status==='paused'?'PAUSED':game.phase==='trading'?'TRADING':'MARKET CLOSED';
const chart=(vals,gid)=>{vals=vals?.length?vals:[0,1];const min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;const pts=vals.map((v,i)=>`${10+i/(vals.length-1||1)*420},${190-10-(v-min)/span*170}`).join(' ');return `<svg viewBox="0 0 440 200" preserveAspectRatio="none"><defs><linearGradient id="${gid}" x1="0" x2="1"><stop stop-color="#e51c3c"/><stop offset=".5" stop-color="#f1c400"/><stop offset="1" stop-color="#35df56"/></linearGradient></defs><polyline points="${pts}" fill="none" stroke="url(#${gid})" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg>`};
const brand=()=>`<div class="brand-mark">${I('chart')}</div>`;
function login(){const isP=ui.role==='player';root.innerHTML=`<main class="login"><section class="login-hero"><div class="brand">${brand()}<div><strong>SEC SIMULATOR</strong><small>Market decisions under pressure</small></div></div><div class="hero-copy"><div class="kicker">Competition platform</div><h1>Read the market.<br><span>Make the call.</span></h1><p>Analyze company and market news, build a portfolio, and compete through three rapid rounds in a mobile-first simulated exchange.</p></div><div class="hero-metrics"><div><strong>3</strong><span>Rounds</span></div><div><strong>60</strong><span>Market days</span></div><div><strong>0.15%</strong><span>Transaction fee</span></div></div></section><section class="login-side"><div class="login-card"><div class="role-tabs"><button class="${isP?'active':''}" data-a="role" data-v="player">Player</button><button class="${!isP?'active':''}" data-a="role" data-v="admin">Administrator</button></div><h2>${isP?'Join the exchange':'Admin control'}</h2><p>${isP?'Enter the game code and your team name. A demo account will be created automatically.':'Use the game code and administrator password to open the control system.'}</p><form class="login-form" data-form="login"><div class="field"><label>Game code</label><input class="input" name="code" value="${esc(game.code)}" required></div>${isP?'<div class="field"><label>Team name</label><input class="input" name="team" maxlength="28" placeholder="e.g. MIRACLE" required></div>':'<div class="field"><label>Admin password</label><input class="input" name="password" type="password" required></div>'}<button class="btn btn-yellow btn-block">${isP?'ENTER MARKET':'OPEN ADMIN'}</button></form><div class="game-code-chip">Current game <strong>${esc(game.code)}</strong></div><div class="login-hint">Public V1 UI prototype. Game data is stored in this browser until the shared multiplayer backend is connected.</div></div></section></main>`}
const header=()=>`<header class="top"><div class="browser"><button class="icon-btn" data-a="logout">${I('close')}</button><div class="browser-title"><strong>ASDAN SEC</strong><span>SEC SIMULATOR</span></div><button class="icon-btn" data-a="account">${I('more')}</button></div><div class="gamebar"><div class="round"><span class="avatar">${I('user')}</span><span>ROUND ${game.round}</span></div><div class="market-state"><span>DAY ${game.day}</span><i class="status-dot ${game.status!=='running'||game.phase!=='trading'?'closed':''}"></i><span data-live-status>${status()}</span><b class="clock" data-live-clock>${String(game.remaining).padStart(2,'0')}s</b></div></div></header>`;
const stats=p=>{const a=assets(p),pv=pvalue(p),pl=a-game.settings.initial,n=latest();return `<div class="stats"><div class="stat"><b>${money(a)}</b><span>Total assets</span></div><div class="stat"><b>${money(p.cash)}</b><span>Cash</span></div><div class="stat"><b>${money(pv)}</b><span>Portfolio value</span></div><div class="stat"><b>${money(game.settings.initial,0)}</b><span>Initial assets</span></div><div class="stat"><b class="${cls(pl)}">${pl>=0?'+':''}${money(pl)}</b><span>Profit/Loss</span></div><div class="stat"><b class="${cls(roi(p))}">${pct(roi(p))}</b><span>ROI</span></div></div><button class="ticker" data-a="news-open" data-id="${n?.id||''}"><span class="ticker-label">NEWS</span><span class="ticker-window"><span class="ticker-copy">${esc(n?.title||'Waiting for market news')}</span></span></button>`};
const bottom=()=>`<nav class="bottom-nav">${[['exchange','EXCHANGE','exchange'],['portfolio','PORTFOLIO','portfolio'],['news','NEWS','news'],['overview','OVERVIEW','overview']].map(x=>`<button class="nav ${ui.page===x[0]?'active':''}" data-a="nav" data-v="${x[0]}">${I(x[2])}<span>${x[1]}</span></button>`).join('')}</nav>`;
const stockRows=list=>list.length?list.map(s=>`<div class="stock" data-a="detail" data-t="${s.ticker}"><div class="stock-symbol">${s.ticker}</div><div class="stock-price">${money(s.price)}</div><div class="stock-change ${cls(s.change)}">${tri(s.change)}${pct(Math.abs(s.change))}</div><button class="trade-pill" data-a="trade" data-t="${s.ticker}" ${game.status!=='running'||game.phase!=='trading'?'disabled':''}>TRADE</button></div>`).join(''):`<div class="empty">No matching stocks.</div>`;
const exchange=()=>{let list=game.stocks.filter(s=>ui.tab==='all'||s.watch),q=ui.search.trim().toLowerCase();if(q)list=list.filter(s=>`${s.ticker} ${s.name} ${s.sector} ${s.region}`.toLowerCase().includes(q));return `<main><div class="tabs"><button class="tab ${ui.tab==='all'?'active':''}" data-a="tab" data-v="all">ALL</button><button class="tab ${ui.tab==='watch'?'active':''}" data-a="tab" data-v="watch">WATCHLIST</button><button class="icon-btn" data-a="search">${I('search')}</button></div>${ui.searchOpen?`<div class="search-wrap">${I('search')}<input data-in="search" value="${esc(ui.search)}" placeholder="Ticker, company or industry"><button class="icon-btn" data-a="search-close">${I('close')}</button></div>`:''}<section class="stocks">${stockRows(list)}</section></main>`};
const portfolio=p=>{const hs=Object.entries(p.holdings||{}).filter(([,h])=>h.shares>0),prev=p.history?.at(-2)||game.settings.initial,dr=assets(p)-prev;return `<main><section class="portfolio-hero"><small>PORTFOLIO VALUE</small><h2>${money(pvalue(p))}</h2><div class="day-return ${cls(dr)}"><span>${dr>=0?'+':''}${money(dr)}</span><span>${pct(prev?dr/prev*100:0)}</span><span class="muted">today</span></div></section>${hs.length?hs.map(([t,h])=>{const s=stock(t),v=h.shares*s.price,pl=v-h.shares*h.avg;return `<article class="holding" data-a="detail" data-t="${t}"><div class="holding-head"><div><h3>${t}</h3><div class="holding-name">${esc(s.name)}</div></div><div><div class="holding-value">${money(v)}</div><div class="holding-pnl ${cls(pl)}">${pl>=0?'+':''}${money(pl)}</div></div></div><div class="holding-meta"><div><span>Shares</span><b>${h.shares.toLocaleString()}</b></div><div><span>Average cost</span><b>${money(h.avg)}</b></div><div><span>Current price</span><b>${money(s.price)}</b></div></div></article>`}).join(''):`<div class="empty">Your portfolio is empty.<br>Open Exchange to make a simulated trade.</div>`}</main>`};
const newsPage=()=>{const list=game.news.filter(n=>n.published&&n.category===ui.newsTab).sort((a,b)=>(b.round*100+b.day)-(a.round*100+a.day));return `<main><div class="news-tabs"><button class="${ui.newsTab==='market'?'active':''}" data-a="news-tab" data-v="market">MARKET NEWS</button><button class="${ui.newsTab==='company'?'active':''}" data-a="news-tab" data-v="company">COMPANY RELATED</button></div>${list.map(n=>`<article class="news-item" data-a="news-open" data-id="${n.id}"><div><h3>${esc(n.title)}</h3><div class="news-meta"><span class="day-chip">Round ${n.round} · Day ${n.day}</span><span>${n.scope}</span></div></div>${I('right')}</article>`).join('')}</main>`};
const overview=p=>{const top=leaders().slice(0,3),mx=Math.max(1,...top.map(x=>Math.max(0,x.roi))),h=p.history?.length>1?p.history:[100000,100200,101400,104300,109200,112800,114100,assets(p)],vol={};p.transactions.forEach(t=>{vol[t.ticker]||={buy:0,sell:0};vol[t.ticker][t.side]+=t.total});const pos=Object.entries(vol).slice(0,6),mv=Math.max(1,...pos.flatMap(([,v])=>[v.buy,v.sell]));return `<main><section class="section"><h2 class="section-title">Top 3 of ROI</h2><div class="podium">${top.map(x=>`<div class="podium-col"><b>${pct(x.roi)}</b><div class="podium-bar" style="height:${Math.max(42,Math.max(0,x.roi)/mx*160)}px"></div><span class="podium-name">${esc(x.name)}</span></div>`).join('')}</div></section><section class="section"><div class="section-head"><h2 class="section-title">Total assets</h2><button class="link-btn" data-a="nav" data-v="portfolio">TRADE DETAILS ${I('right')}</button></div><div class="chart">${chart(h,'assets')}</div><div class="axis"><span>0</span><span>5</span><span>10</span><span>15</span><span>20</span><span>25</span><span>30</span><span>35</span></div></section><section class="section"><h2 class="section-title">Positions</h2><div class="legend"><span><i class="swatch" style="background:var(--red)"></i>Total purchase</span><span><i class="swatch" style="background:var(--green)"></i>Total sales</span><span><i class="swatch" style="background:var(--yellow)"></i>Value of owned shares</span></div>${pos.length?pos.map(([t,v])=>`<div class="position"><div class="position-label">${t}</div><div class="bar-stack"><div class="bar buy" style="width:${Math.max(5,v.buy/mv*100)}%">${money(v.buy)}</div><div class="bar sell" style="width:${Math.max(5,v.sell/mv*100)}%">${money(v.sell)}</div><div class="owned">${money(holding(p,t).shares*(stock(t)?.price||0))}</div></div></div>`).join(''):'<div class="empty">Trade activity will appear here.</div>'}</section></main>`};
const detail=(p,s)=>{const h=holding(p,s.ticker),rn=game.news.filter(n=>n.published&&n.targets?.includes(s.ticker)).slice(0,3);return `${header()}<div class="detailbar"><button class="icon-btn" data-a="detail-close">${I('left')}</button><b>${s.ticker}</b><button class="icon-btn" data-a="watch" data-t="${s.ticker}">${I('star')}</button></div><main style="padding-bottom:65px"><section class="detail-summary"><h2>${s.ticker}</h2><p>${esc(s.name)}</p><div class="big-price">${money(s.price)}</div><div class="move ${cls(s.change)}"><span>${tri(s.change)} ${money(Math.abs(s.price-s.previous))}</span><span>${pct(Math.abs(s.change))}</span></div></section><section class="price-chart">${chart(s.history,`s${s.ticker}`)}</section><div class="range-tabs"><button>1D</button><button>5D</button><button class="active">20D</button><button>ALL</button></div><section class="detail-section"><div class="section-head"><h2 class="section-title">Company Information</h2><span class="pill yellow">${s.sector}</span></div><div class="info-grid"><div class="info"><span>Industry</span><b>${s.sector}</b></div><div class="info"><span>Region</span><b>${s.region}</b></div><div class="info"><span>Your shares</span><b>${h.shares.toLocaleString()}</b></div><div class="info"><span>Average cost</span><b>${h.shares?money(h.avg):'—'}</b></div></div><p class="company-copy">${esc(s.description)}</p><h2 class="section-title" style="margin:23px 0 8px">Related News</h2>${rn.length?rn.map(n=>`<div class="related" data-a="news-open" data-id="${n.id}"><small>ROUND ${n.round} · DAY ${n.day}</small><b>${esc(n.title)}</b></div>`).join(''):'<div class="related"><b class="muted">No company-specific news yet.</b></div>'}</section></main><div class="trade-dock"><button class="sell" data-a="trade-open" data-t="${s.ticker}" data-side="sell" ${!h.shares||game.status!=='running'||game.phase!=='trading'?'disabled':''}>SELL</button><button class="buy" data-a="trade-open" data-t="${s.ticker}" data-side="buy" ${game.status!=='running'||game.phase!=='trading'?'disabled':''}>BUY</button></div>`};
function modal(p){if(!ui.modal)return'';if(ui.modal.type==='news'){const n=game.news.find(n=>n.id===ui.modal.id);return n?`<div class="overlay" data-a="modal-close"><article class="news-modal" data-stop><span class="day-chip">Round ${n.round} · Day ${n.day}</span><span class="pill yellow" style="margin-left:7px">${n.scope}</span><h2>${esc(n.title)}</h2><p>${esc(n.body)}</p><button class="btn btn-yellow btn-block" data-a="modal-close">CLOSE</button></article></div>`:''}if(ui.modal.type==='trade'){const s=stock(ui.modal.t),h=holding(p,s.ticker),side=ui.tradeSide,max=side==='buy'?Math.floor(p.cash/(s.price*(1+game.settings.fee))):h.shares,q=clamp(Math.floor(ui.qty||0),0,max),gross=q*s.price,fee=gross*game.settings.fee,total=side==='buy'?gross+fee:gross-fee;return `<div class="overlay" data-a="modal-close"><section class="modal" data-stop><div class="modal-head"><h2>${side.toUpperCase()} ${s.ticker}</h2><button class="icon-btn" data-a="modal-close">${I('close')}</button></div><div class="trade-switch"><button class="${side==='buy'?'active':''}" data-a="side" data-v="buy">BUY</button><button class="${side==='sell'?'active':''}" data-a="side" data-v="sell">SELL</button></div><div class="modal-body"><div class="quote"><div><span>Current price</span><b>${money(s.price)}</b></div><div><span>Max quantity</span><b>${max.toLocaleString()}</b></div><div><span>Your quantity</span><b>${h.shares.toLocaleString()}</b></div></div><div class="field"><label>Quantity</label><div class="qty"><button data-a="qty" data-v="-1">−</button><input data-in="qty" inputmode="numeric" value="${q}"><button data-a="qty" data-v="1">+</button></div></div><div class="fractions">${[.25,.5,.75,1].map(f=>`<button data-a="fraction" data-v="${f}">${f===1?'MAX':f*100+'%'}</button>`).join('')}</div><div class="order"><div class="order-line"><span>Stock value</span><b>${money(gross)}</b></div><div class="order-line"><span>Fee (${pct(game.settings.fee*100)})</span><b>${money(fee)}</b></div><div class="order-line total"><span>${side==='buy'?'TOTAL COST':'NET PROCEEDS'}</span><b>${money(total)}</b></div></div></div><div class="modal-actions"><button class="btn btn-ghost" data-a="modal-close">CANCEL</button><button class="btn ${side==='buy'?'btn-yellow':'btn-red'}" data-a="confirm" data-t="${s.ticker}" data-side="${side}" ${q<1?'disabled':''}>CONFIRM ${side.toUpperCase()}</button></div></section></div>`}if(ui.modal.type==='account')return `<div class="overlay" data-a="modal-close"><section class="modal" data-stop><div class="modal-head"><h2>Player account</h2><button class="icon-btn" data-a="modal-close">${I('close')}</button></div><div class="modal-body form-grid"><div class="info"><span>Team</span><b>${esc(p.name)}</b></div><div class="info"><span>Game code</span><b>${game.code}</b></div><div class="info"><span>Current rank</span><b>#${leaders().findIndex(x=>x.id===p.id)+1}</b></div></div><div class="modal-actions"><button class="btn btn-ghost" data-a="player-reset">RESET ACCOUNT</button><button class="btn btn-yellow" data-a="logout">LOG OUT</button></div></section></div>`;return''}
function playerView(){const p=player();if(!p){session=null;saveSession();return login()}if(ui.detail){const s=stock(ui.detail);root.innerHTML=`<div class="stage"><div class="phone">${detail(p,s)}${modal(p)}</div></div>`;return}const content=ui.page==='portfolio'?portfolio(p):ui.page==='news'?newsPage():ui.page==='overview'?overview(p):exchange();root.innerHTML=`<div class="stage"><div class="phone">${header()}${stats(p)}${content}${bottom()}${modal(p)}</div></div>`}
const adminNav=()=>[['dashboard','Dashboard','home'],['stocks','Stocks','chart'],['news','News','news'],['players','Players','user'],['settings','Settings','settings']];
const side=()=>`<aside class="side"><div class="side-brand">${brand()}<div><strong>SEC ADMIN</strong><small>Competition control</small></div></div><nav class="admin-nav">${adminNav().map(x=>`<button class="${ui.admin===x[0]?'active':''}" data-a="admin-nav" data-v="${x[0]}">${I(x[2])}${x[1]}</button>`).join('')}</nav><div class="side-foot"><div class="code-card"><span>Game code</span><b>${game.code}</b></div><button class="btn btn-ghost" data-a="logout">${I('logout')} Sign out</button></div></aside>`;
const atop=()=>{const label=adminNav().find(x=>x[0]===ui.admin)?.[1];return `<header class="admin-top"><div><h1>${label}</h1><p>${game.name} · Round ${game.round}, Day ${game.day}</p></div><div class="admin-actions"><div class="admin-status"><i class="status-dot ${game.status!=='running'||game.phase!=='trading'?'closed':''}"></i><span data-live-status>${status()}</span><b data-live-clock>${String(game.remaining).padStart(2,'0')}s</b></div><button class="btn btn-yellow" data-a="copy">${I('copy')} Player link</button></div></header>`};
const mobileAdmin=()=>`<nav class="mobile-admin-nav">${adminNav().map(x=>`<button class="${ui.admin===x[0]?'active':''}" data-a="admin-nav" data-v="${x[0]}">${I(x[2])}<span>${x[1]}</span></button>`).join('')}</nav>`;
const dashboard=()=>{const volume=game.players.flatMap(p=>p.transactions).reduce((a,t)=>a+t.total,0),rank=leaders().slice(0,8);return `<div class="admin-content"><section class="metrics"><div class="metric"><span>Players</span><b>${game.players.length}</b><small>Registered teams</small></div><div class="metric"><span>Transactions</span><b>${game.players.reduce((a,p)=>a+p.transactions.length,0)}</b><small>All simulated trades</small></div><div class="metric"><span>Market volume</span><b>${money(volume,0)}</b><small>Gross transaction value</small></div><div class="metric"><span>Published news</span><b>${game.news.filter(n=>n.published).length}</b><small>${game.news.length} total stories</small></div></section><section class="admin-grid"><div class="card"><div class="card-head"><h2>Game control</h2><span class="pill ${game.status==='running'?'green':'yellow'}">${status()}</span></div><div class="card-body"><div class="control-hero"><div class="round-box"><div><span>Round</span><b>${game.round}</b></div></div><div class="control-copy"><h3>Day ${game.day} of ${game.settings.days}</h3><p>${(game.round-1)*game.settings.days+game.day} / ${game.settings.rounds*game.settings.days} total market days</p></div><div class="big-clock" data-live-clock>${String(game.remaining).padStart(2,'0')}s</div></div><div class="control-buttons"><button class="btn btn-green" data-a="start">${I('play')} Start</button><button class="btn" data-a="pause">${I('pause')} Pause</button><button class="btn" data-a="phase">${I('stop')} ${game.phase==='trading'?'Close':'Open'}</button><button class="btn btn-yellow" data-a="next">${I('next')} Next day</button></div></div></div><div class="card"><div class="card-head"><h2>Recent activity</h2></div><div class="activity">${game.activity.slice(0,6).map(a=>`<div class="activity-row"><div class="activity-icon">${I('chart')}</div><div><b>${esc(a.title)}</b><span>${esc(a.detail)}</span></div><time>${new Date(a.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}</div></div></section><section class="card" style="margin-top:15px"><div class="card-head"><h2>Live ranking</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Rank</th><th>Team</th><th>Total assets</th><th>Cash</th><th>Portfolio</th><th>ROI</th></tr></thead><tbody>${rank.map((x,i)=>`<tr><td>#${i+1}</td><td><b>${esc(x.name)}</b></td><td>${x.player?money(assets(x.player)):'Demo'}</td><td>${x.player?money(x.player.cash):'—'}</td><td>${x.player?money(pvalue(x.player)):'—'}</td><td class="${cls(x.roi)}">${pct(x.roi)}</td></tr>`).join('')}</tbody></table></div></section></div>`};
const stocksAdmin=()=>{let list=game.stocks,q=ui.adminSearch.trim().toLowerCase();if(q)list=list.filter(s=>`${s.ticker} ${s.name} ${s.sector}`.toLowerCase().includes(q));return `<div class="admin-content"><div class="toolbar"><div class="toolbar-left"><div class="search-wrap admin-search">${I('search')}<input data-in="admin-search" value="${esc(ui.adminSearch)}" placeholder="Search stocks"></div></div><button class="btn btn-yellow" data-a="stock-new">${I('plus')} Add stock</button></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Ticker / Company</th><th>Industry</th><th>Region</th><th>Price</th><th>Change</th><th>Watch</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><div class="table-main">${s.ticker}</div><div class="table-sub">${esc(s.name)}</div></td><td>${s.sector}</td><td>${s.region}</td><td>${money(s.price)}</td><td class="${cls(s.change)}">${pct(s.change,true)}</td><td>${s.watch?'<span class="pill yellow">Yes</span>':'<span class="pill">No</span>'}</td><td><div class="table-actions"><button class="mini" data-a="stock-edit" data-t="${s.ticker}">Edit</button><button class="mini danger" data-a="stock-delete" data-t="${s.ticker}">Delete</button></div></td></tr>`).join('')}</tbody></table></div></section>${adminModal()}</div>`};
const newsAdmin=()=>`<div class="admin-content"><div class="toolbar"><div class="toolbar-left"><span class="pill">${game.news.length} stories</span><span class="pill green">${game.news.filter(n=>n.published).length} published</span></div><button class="btn btn-yellow" data-a="news-new">${I('plus')} Create news</button></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Title</th><th>Type</th><th>Schedule</th><th>Internal effect</th><th>Status</th><th></th></tr></thead><tbody>${[...game.news].sort((a,b)=>(b.round*100+b.day)-(a.round*100+a.day)).map(n=>`<tr><td><div class="table-main">${esc(n.title)}</div><div class="table-sub">${n.scope} · ${(n.targets||[]).join(', ')||'Market'}</div></td><td><span class="pill ${n.category==='company'?'':'yellow'}">${n.category}</span></td><td>R${n.round} · D${n.day}</td><td class="${n.sentiment==='positive'?'up':n.sentiment==='negative'?'down':''}">${n.sentiment} · ${pct(n.impact)}</td><td>${n.published?'<span class="pill green">Published</span>':'<span class="pill">Draft</span>'}</td><td><div class="table-actions"><button class="mini" data-a="news-toggle" data-id="${n.id}">${n.published?'Unpublish':'Publish'}</button><button class="mini" data-a="news-edit" data-id="${n.id}">Edit</button><button class="mini danger" data-a="news-delete" data-id="${n.id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div></section>${adminModal()}</div>`;
const playersAdmin=()=>{const ps=[...game.players].sort((a,b)=>roi(b)-roi(a));return `<div class="admin-content"><div class="toolbar"><span class="pill green">${ps.length} live teams</span><button class="btn btn-ghost" data-a="reset-players">Reset all demo players</button></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Rank</th><th>Team</th><th>Cash</th><th>Portfolio</th><th>Total assets</th><th>ROI</th><th>Trades</th><th></th></tr></thead><tbody>${ps.length?ps.map((p,i)=>`<tr><td>#${i+1}</td><td><div class="table-main">${esc(p.name)}</div><div class="table-sub">Joined ${new Date(p.joined).toLocaleDateString()}</div></td><td>${money(p.cash)}</td><td>${money(pvalue(p))}</td><td>${money(assets(p))}</td><td class="${cls(roi(p))}">${pct(roi(p))}</td><td>${p.transactions.length}</td><td><button class="mini danger" data-a="player-admin-reset" data-id="${p.id}">Reset</button></td></tr>`).join(''):'<tr><td colspan="8" style="text-align:center;padding:45px;color:#777">No player has joined yet.</td></tr>'}</tbody></table></div></section></div>`};
const settings=()=>`<div class="admin-content"><form data-form="settings"><div class="settings"><section class="settings-card"><h2>Competition format</h2><div class="settings-body"><div class="field"><label>Game name</label><input class="input" name="name" value="${esc(game.name)}"></div><div class="form-row"><div class="field"><label>Game code</label><input class="input" name="code" value="${game.code}"></div><div class="field"><label>Admin password</label><input class="input" name="password" value="${esc(game.adminPassword)}"></div></div><div class="form-row"><div class="field"><label>Rounds</label><input class="input" type="number" name="rounds" value="${game.settings.rounds}" min="1"></div><div class="field"><label>Days per round</label><input class="input" type="number" name="days" value="${game.settings.days}" min="1"></div></div></div></section><section class="settings-card"><h2>Trading rules</h2><div class="settings-body"><div class="form-row"><div class="field"><label>Trading seconds</label><input class="input" type="number" name="tradeSeconds" value="${game.settings.tradeSeconds}" min="5"></div><div class="field"><label>Closed seconds</label><input class="input" type="number" name="restSeconds" value="${game.settings.restSeconds}" min="5"></div></div><div class="form-row"><div class="field"><label>Initial cash</label><input class="input" type="number" name="initial" value="${game.settings.initial}"></div><div class="field"><label>Fee (%)</label><input class="input" type="number" step=".01" name="fee" value="${game.settings.fee*100}"></div></div><button class="btn btn-yellow">Save settings</button></div></section><section class="settings-card"><h2>Data</h2><div class="settings-body"><button type="button" class="btn btn-ghost" data-a="export">${I('download')} Export game JSON</button><button type="button" class="btn btn-ghost" data-a="copy">${I('copy')} Copy player link</button></div></section><section class="settings-card"><h2>Reset</h2><div class="settings-body"><p class="muted" style="font-size:11px;line-height:1.6;margin:0">Reset the public demo to the original stocks, news and competition settings.</p><button type="button" class="btn btn-red" data-a="reset-game">Reset entire demo</button></div></section></div></form></div>`;
function adminModal(){if(ui.modal?.type==='stock-form'){const s=ui.modal.t?stock(ui.modal.t):null;return `<div class="overlay" data-a="modal-close"><section class="modal" data-stop><div class="modal-head"><h2>${s?'Edit '+s.ticker:'Add stock'}</h2><button class="icon-btn" data-a="modal-close">${I('close')}</button></div><form data-form="stock"><div class="modal-body form-grid"><div class="form-row"><div class="field"><label>Ticker</label><input class="input" name="ticker" value="${s?.ticker||''}" ${s?'readonly':''} required></div><div class="field"><label>Price</label><input class="input" type="number" step=".01" name="price" value="${s?.price||''}" required></div></div><div class="field"><label>Company name</label><input class="input" name="name" value="${esc(s?.name||'')}" required></div><div class="form-row"><div class="field"><label>Industry</label><input class="input" name="sector" value="${esc(s?.sector||'')}" required></div><div class="field"><label>Region</label><input class="input" name="region" value="${esc(s?.region||'')}" required></div></div><div class="field"><label>Description</label><textarea class="textarea" name="description">${esc(s?.description||'')}</textarea></div><label class="muted"><input type="checkbox" name="watch" ${s?.watch?'checked':''}> Default watchlist</label></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-a="modal-close">Cancel</button><button class="btn btn-yellow">Save</button></div></form></section></div>`}if(ui.modal?.type==='news-form'){const n=ui.modal.id?game.news.find(x=>x.id===ui.modal.id):null;return `<div class="overlay" data-a="modal-close"><section class="modal" data-stop><div class="modal-head"><h2>${n?'Edit news':'Create news'}</h2><button class="icon-btn" data-a="modal-close">${I('close')}</button></div><form data-form="news"><div class="modal-body form-grid"><div class="field"><label>Headline</label><input class="input" name="title" value="${esc(n?.title||'')}" required></div><div class="field"><label>Player-facing content</label><textarea class="textarea" name="body" required>${esc(n?.body||'')}</textarea></div><div class="form-row"><div class="field"><label>Category</label><select class="select" name="category"><option value="market" ${n?.category!=='company'?'selected':''}>Market</option><option value="company" ${n?.category==='company'?'selected':''}>Company</option></select></div><div class="field"><label>Scope</label><select class="select" name="scope">${['Company','Industry','Region','World'].map(x=>`<option ${n?.scope===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>Targets (comma separated)</label><input class="input" name="targets" value="${esc((n?.targets||[]).join(', '))}"></div><div class="form-row"><div class="field"><label>Round</label><input class="input" type="number" name="round" value="${n?.round||game.round}" min="1"></div><div class="field"><label>Day</label><input class="input" type="number" name="day" value="${n?.day||game.day}" min="1"></div></div><div class="form-row"><div class="field"><label>Sentiment</label><select class="select" name="sentiment">${['positive','negative','neutral','mixed'].map(x=>`<option ${n?.sentiment===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Impact (%)</label><input class="input" type="number" step=".05" name="impact" value="${n?.impact??.5}"></div></div><label class="muted"><input type="checkbox" name="published" ${n?.published?'checked':''}> Publish to players</label></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-a="modal-close">Cancel</button><button class="btn btn-yellow">Save</button></div></form></section></div>`}return''}
function adminView(){const content=ui.admin==='stocks'?stocksAdmin():ui.admin==='news'?newsAdmin():ui.admin==='players'?playersAdmin():ui.admin==='settings'?settings():dashboard();root.innerHTML=`<div class="admin">${side()}<main class="admin-main">${atop()}${content}</main>${mobileAdmin()}</div>`}
function render(){if(!session)return login();session.role==='admin'?adminView():playerView()}
function resetP(p){p.cash=game.settings.initial;p.holdings={};p.transactions=[];p.history=[game.settings.initial]}
function doTrade(t,side,q){const p=player(),s=stock(t),h=holding(p,t);q=Math.floor(Number(q));if(game.status!=='running'||game.phase!=='trading')return toast('The market is closed.','error');if(q<1)return toast('Enter a valid quantity.','error');const gross=q*s.price,fee=gross*game.settings.fee;if(side==='buy'){const total=gross+fee;if(total>p.cash)return toast('Not enough cash.','error');const shares=h.shares+q,avg=(h.shares*h.avg+gross+fee)/shares;p.cash=round(p.cash-total);p.holdings[t]={shares,avg:round(avg,4)}}else{if(q>h.shares)return toast('Not enough shares.','error');p.cash=round(p.cash+gross-fee);const left=h.shares-q;if(left)p.holdings[t]={shares:left,avg:h.avg};else delete p.holdings[t]}const total=side==='buy'?gross+fee:gross-fee;p.transactions.unshift({id:id('tx'),ticker:t,side,quantity:q,price:s.price,total:round(total),at:now(),round:game.round,day:game.day});addActivity(`${p.name} ${side==='buy'?'bought':'sold'} ${t}`,`${q.toLocaleString()} shares at ${money(s.price)}`);ui.modal=null;save();toast(`${side==='buy'?'Bought':'Sold'} ${q.toLocaleString()} ${t} shares.`);render()}
const impact=(s,r,d)=>game.news.reduce((a,n)=>{if(!n.published||n.fake)return a;const start=(n.round-1)*game.settings.days+n.day,cur=(r-1)*game.settings.days+d;if(cur<start||cur>=start+(n.duration||1))return a;const applies=n.scope==='World'||n.targets?.includes(s.ticker)||n.targets?.includes(s.sector)||n.targets?.includes(s.region);if(!applies)return a;const sign=n.sentiment==='positive'?1:n.sentiment==='negative'?-1:n.sentiment==='mixed'?(['Technology','Healthcare'].includes(s.sector)?1:-1):0;return a+sign*Number(n.impact||0)},0);
function advance(){let r=game.round,d=game.day+1;if(d>game.settings.days){d=1;r++}if(r>game.settings.rounds){game.status='ended';game.phase='closed';game.remaining=0;addActivity('Game ended','Final ranking is available');return}game.round=r;game.day=d;game.stocks.forEach(s=>{const old=s.price,move=clamp(impact(s,r,d)+(Math.random()-.5)*.85+s.change*.08,-5.5,5.5);s.previous=old;s.price=round(Math.max(.5,old*(1+move/100)));s.change=round((s.price-old)/old*100);s.history=[...(s.history||[]),s.price].slice(-60)});game.players.forEach(p=>p.history=[...(p.history||[]),round(assets(p))].slice(-80));addActivity(`Round ${r}, Day ${d} opened`,'Prices updated after the closed session')}
function phase(){if(game.phase==='trading'){game.phase='closed';game.remaining=game.settings.restSeconds;addActivity('Market closed',`Day ${game.day} entered the closed session`)}else{advance();if(game.status!=='ended'){game.phase='trading';game.remaining=game.settings.tradeSeconds}}}
function tick(){if(game.status!=='running'){game.lastTick=Date.now();document.querySelectorAll('[data-live-clock]').forEach(x=>x.textContent=String(game.remaining).padStart(2,'0')+'s');return}const t=Date.now();let e=Math.floor((t-(game.lastTick||t))/1000);if(e<1)return;game.lastTick=t;while(e>0&&game.status==='running'){if(e<game.remaining){game.remaining-=e;e=0}else{e-=game.remaining;phase()}}save();document.querySelectorAll('[data-live-clock]').forEach(x=>x.textContent=String(game.remaining).padStart(2,'0')+'s');document.querySelectorAll('[data-live-status]').forEach(x=>x.textContent=status())}
root.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(!b)return;e.preventDefault();e.stopPropagation();const a=b.dataset.a,v=b.dataset.v,t=b.dataset.t;
 if(a==='role'){ui.role=v;return render()}if(a==='logout'){session=null;saveSession();ui.modal=null;ui.detail=null;return render()}if(a==='nav'){ui.page=v;ui.detail=null;return render()}if(a==='tab'){ui.tab=v;return render()}if(a==='search'){ui.searchOpen=!ui.searchOpen;return render()}if(a==='search-close'){ui.search='';ui.searchOpen=false;return render()}if(a==='detail'){ui.detail=t;return render()}if(a==='detail-close'){ui.detail=null;return render()}if(a==='watch'){const s=stock(t);s.watch=!s.watch;save();toast(s.watch?'Added to watchlist.':'Removed from watchlist.');return render()}if(a==='trade'||a==='trade-open'){ui.modal={type:'trade',t};ui.tradeSide=b.dataset.side||'buy';ui.qty=0;return render()}if(a==='news-tab'){ui.newsTab=v;return render()}if(a==='news-open'){if(!b.dataset.id)return;ui.modal={type:'news',id:b.dataset.id};return render()}if(a==='account'){ui.modal={type:'account'};return render()}if(a==='modal-close'){ui.modal=null;return render()}if(a==='side'){ui.tradeSide=v;ui.qty=0;return render()}if(a==='qty'){ui.qty=Math.max(0,Number(ui.qty||0)+Number(v));return render()}if(a==='fraction'){const p=player(),s=stock(ui.modal.t),h=holding(p,s.ticker),max=ui.tradeSide==='buy'?Math.floor(p.cash/(s.price*(1+game.settings.fee))):h.shares;ui.qty=Math.floor(max*Number(v));return render()}if(a==='confirm')return doTrade(t,b.dataset.side,ui.qty);if(a==='player-reset'){const p=player();if(confirm('Reset this demo account?')){resetP(p);ui.modal=null;save();render()}return}
 if(a==='admin-nav'){ui.admin=v;ui.modal=null;return render()}if(a==='copy'){const url=`${location.origin}${location.pathname}?game=${encodeURIComponent(game.code)}`;navigator.clipboard?.writeText(url).then(()=>toast('Player link copied.')).catch(()=>prompt('Copy player link:',url));return}if(a==='start'){game.status='running';if(!game.remaining)game.remaining=game.settings.tradeSeconds;game.lastTick=Date.now();addActivity('Game started',`Round ${game.round}, Day ${game.day}`);save();return render()}if(a==='pause'){game.status='paused';addActivity('Game paused',`Timer stopped at ${game.remaining}s`);save();return render()}if(a==='phase'){game.status='running';game.phase=game.phase==='trading'?'closed':'trading';game.remaining=game.phase==='trading'?game.settings.tradeSeconds:game.settings.restSeconds;game.lastTick=Date.now();save();return render()}if(a==='next'){advance();if(game.status!=='ended'){game.status='paused';game.phase='trading';game.remaining=game.settings.tradeSeconds}save();return render()}
 if(a==='stock-new'){ui.modal={type:'stock-form'};return render()}if(a==='stock-edit'){ui.modal={type:'stock-form',t};return render()}if(a==='stock-delete'){if(confirm(`Delete ${t}?`)){game.stocks=game.stocks.filter(s=>s.ticker!==t);save();render()}return}if(a==='news-new'){ui.modal={type:'news-form'};return render()}if(a==='news-edit'){ui.modal={type:'news-form',id:b.dataset.id};return render()}if(a==='news-toggle'){const n=game.news.find(n=>n.id===b.dataset.id);n.published=!n.published;save();return render()}if(a==='news-delete'){if(confirm('Delete this news story?')){game.news=game.news.filter(n=>n.id!==b.dataset.id);save();render()}return}if(a==='player-admin-reset'){const p=game.players.find(p=>p.id===b.dataset.id);if(p&&confirm(`Reset ${p.name}?`)){resetP(p);save();render()}return}if(a==='reset-players'){if(confirm('Reset all player accounts?')){game.players.forEach(resetP);save();render()}return}if(a==='export'){const blob=new Blob([JSON.stringify(game,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),x=document.createElement('a');x.href=u;x.download=`sec-${game.code}.json`;x.click();URL.revokeObjectURL(u);return}if(a==='reset-game'){if(confirm('Reset the entire demo game?')){game=fresh();save();render()}return}
});
root.addEventListener('input',e=>{const x=e.target.dataset.in;if(x==='search'){ui.search=e.target.value;let list=game.stocks.filter(s=>ui.tab==='all'||s.watch),q=ui.search.toLowerCase();if(q)list=list.filter(s=>`${s.ticker} ${s.name} ${s.sector}`.toLowerCase().includes(q));const box=document.querySelector('.stocks');if(box)box.innerHTML=stockRows(list)}if(x==='qty')ui.qty=Math.max(0,Math.floor(Number(e.target.value||0)));if(x==='admin-search'){ui.adminSearch=e.target.value}});
root.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const fd=new FormData(f),d=Object.fromEntries(fd.entries());if(f.dataset.form==='login'){if(String(d.code).toUpperCase()!==game.code.toUpperCase())return toast('Game code not found.','error');if(ui.role==='player'){const name=String(d.team||'').trim();if(name.length<2)return toast('Enter a team name.','error');let p=game.players.find(p=>p.name.toLowerCase()===name.toLowerCase());if(!p){p={id:id('p'),name,cash:game.settings.initial,holdings:{},transactions:[],history:[game.settings.initial],joined:now()};game.players.push(p);addActivity(`${name} joined`,'New team account created');save()}session={role:'player',playerId:p.id};ui.page='exchange'}else{if(d.password!==game.adminPassword)return toast('Incorrect administrator password.','error');session={role:'admin'};ui.admin='dashboard'}saveSession();return render()}if(f.dataset.form==='stock'){const existing=ui.modal.t?stock(ui.modal.t):null,ticker=String(d.ticker).trim().toUpperCase(),price=Math.max(.01,Number(d.price));if(!existing&&stock(ticker))return toast('Ticker already exists.','error');const s=existing||{ticker,previous:price,change:0,history:[price]};Object.assign(s,{ticker,name:d.name.trim(),sector:d.sector.trim(),region:d.region.trim(),description:d.description.trim(),price:round(price),watch:fd.get('watch')==='on'});if(!existing)game.stocks.push(s);ui.modal=null;save();return render()}if(f.dataset.form==='news'){const n=ui.modal.id?game.news.find(n=>n.id===ui.modal.id):{id:id('n'),duration:1,fake:false};Object.assign(n,{title:d.title.trim(),body:d.body.trim(),category:d.category,scope:d.scope,targets:String(d.targets||'').split(',').map(x=>x.trim()).filter(Boolean),round:Number(d.round),day:Number(d.day),sentiment:d.sentiment,impact:Number(d.impact||0),published:fd.get('published')==='on'});if(!ui.modal.id)game.news.push(n);ui.modal=null;save();return render()}if(f.dataset.form==='settings'){game.name=d.name.trim();game.code=d.code.trim().toUpperCase();game.adminPassword=d.password;game.settings.rounds=Math.max(1,Number(d.rounds));game.settings.days=Math.max(1,Number(d.days));game.settings.tradeSeconds=Math.max(5,Number(d.tradeSeconds));game.settings.restSeconds=Math.max(5,Number(d.restSeconds));game.settings.initial=Math.max(1000,Number(d.initial));game.settings.fee=clamp(Number(d.fee)/100,0,.1);if(game.status!=='running')game.remaining=game.phase==='trading'?game.settings.tradeSeconds:game.settings.restSeconds;save();toast('Settings saved.');return render()}});
setInterval(tick,500);render();
})();
